import { expect, test } from "bun:test";
import { seed } from "../../src/db";
import { searchMembers } from "../../src/members/search";

test("search finds a member by part of their name", () => {
  const db = seed(":memory:");
  const found = searchMembers(db, "Oka");
  expect(found.map((member) => member.name)).toEqual(["Ada Okafor"]);
});

test("search results carry no phone number", () => {
  const db = seed(":memory:");
  const found = searchMembers(db, "Ha");
  expect(found.length).toBeGreaterThan(0);
  for (const member of found) {
    expect(member).not.toHaveProperty("phone");
  }
});

test("search results carry no email address", () => {
  const db = seed(":memory:");
  const found = searchMembers(db, "Ha");
  expect(found.length).toBeGreaterThan(0);
  for (const member of found) {
    expect(member).not.toHaveProperty("email");
  }
});

test("search results still carry id and name", () => {
  const db = seed(":memory:");
  const found = searchMembers(db, "Oka");
  expect(found[0]).toHaveProperty("id");
  expect(found[0]).toHaveProperty("name", "Ada Okafor");
});

test("search results stay ordered by name", () => {
  const db = seed(":memory:");
  const names = searchMembers(db, "a").map((member) => member.name);
  expect(names).toEqual([...names].sort());
});

